// contractAssertBeginSmoke asserts Begin survives a call.
func contractAssertBeginSmoke(
	tb testing.TB,
	c Contract,
) {
	tb.Helper()
	suite.Survives(tb, contractBegin, func(ctx context.Context) {
		_, _ = c.Begin(ctx)
	})
}

