func (contractSatInertBegin) Begin(_ context.Context) (z0 tx.Tx, z1 error) {
	return
}

// contractSatFlickerBegin answers zeros every second
// call, where Begin should answer the same thing twice.
//
// The defect every stability claim names: cacheable, deterministic,
// consistent, non-decreasing are all about two calls agreeing, and a subject
// that answers zeros *forever* agrees with itself perfectly. Only an answer
// that changes breaks them, and alternating with the zero is the smallest
// change available at any return type.
type contractSatFlickerBegin struct {
	tx.Contract
	flip atomic.Int64
}

func (m *contractSatFlickerBegin) Begin(p0 context.Context) (z0 tx.Tx, z1 error) {
	if m.flip.Add(1)%2 == 0 {
		return
	}
	return m.Contract.Begin(p0)
}

// contractSatSputterBegin alternates a minted refusal
// with the real answer where Begin should be steady.
type contractSatSputterBegin struct {
	tx.Contract
	flip atomic.Int64
}

func (m *contractSatSputterBegin) Begin(p0 context.Context) (z0 tx.Tx, z1 error) {
	if m.flip.Add(1)%2 == 1 {
		z1 = errors.New("contract: saturation sputtered a refusal")
		return
	}
	return m.Contract.Begin(p0)
}

// contractSatSpillBegin refuses while answering what
// Begin actually found — whatever the failed lookup left behind.
//
// Every refusal the wardrobe mints elsewhere arrives with the zero value
// beside it, and the value a failed read is supposed to answer is usually the
// zero. So the defect and the claim agree, and a law about what an error must
// coincide with has nothing that can disagree with it.
type contractSatSpillBegin struct{ tx.Contract }

func (m contractSatSpillBegin) Begin(p0 context.Context) (tx.Tx, error) {
	out, err := m.Contract.Begin(p0)
	if err != nil {
		return out, err
	}
	return out, errors.New("contract: saturation spilled a found value into a refusal")
}

// contractSatFlapBegin alternates the fixture pair where
// Begin should answer the store.
type contractSatFlapBegin struct {
	tx.Contract
	flip atomic.Int64
	a, b tx.Tx
}

func (m *contractSatFlapBegin) Begin(_ context.Context) (tx.Tx, error) {
	if m.flip.Add(1)%2 == 0 {
		return m.a, nil
	}
	return m.b, nil
}

